namespace ghidra.app.plugin.core.codebrowser;

using static org.junit.Assert;

using org.junit;

using ghidra.app.plugin.core.marker;
using ghidra.app.plugin.core.navigation;
using ghidra.app.plugin.core.navigation.locationreferences;
using ghidra.app.services;
using ghidra.framework.plugintool;
using ghidra.program.database;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.program.util;
using ghidra.test;
using ghidra.test;

public class CodeBrowserNavigation8051Test : AbstractGhidraHeadedIntegrationTest {
	private TestEnv env;
	private PluginTool tool;
	private AddressFactory addrFactory;
	private Program program;
	private CodeBrowserPlugin cb;

	private Address addr(string address) {
		return addrFactory.getAddress(address);
	}

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getTool();
		tool.addPlugin(typeof(CodeBrowserPlugin).getName());
		tool.addPlugin(typeof(NextPrevAddressPlugin).getName());
		tool.addPlugin(typeof(LocationReferencesPlugin).getName());
		tool.addPlugin(typeof(MarkerManagerPlugin).getName());
		cb = env.getPlugin(typeof(CodeBrowserPlugin));
	}

	/* @After */
	public void tearDown() {
		env.dispose();
	}

	private void loadProgram(string programName)
    {
		program = buildProgram();
		ProgramManager pm = tool.getService(typeof(ProgramManager));
		pm.openProgram(program.getDomainFile());
		addrFactory = program.getAddressFactory();
	}

	private Program buildProgram()
    {
		ProgramBuilder builder = new ProgramBuilder("Test", ProgramBuilder._8051);
		builder.createMemory("CODE", "CODE:0000", 0x1948);
		builder.createMemory("INTMEM", "INTMEM:20", 0xe0);
		builder.setBytes("CODE:07ea", "f5 55", true);
		builder.setBytes("CODE:03f8", "30 02 03", true);
		builder.setBytes("CODE:0595", "75 55 1b", true);

		builder.createEmptyFunction("FUN1", "CODE:03f0", 0x20, DataType.DEFAULT);
		builder.createEmptyFunction("FUN2", "CODE:07d0", 0x20, DataType.DEFAULT);
		return builder.getProgram();
	}

	/* @Test */
	public void testOperandNavigation()
    {
		loadProgram("test");
		env.showTool();
		waitForSwing();
		cb.goTo(new OperandFieldLocation(program, addr("CODE:07ea"), null, null, null, 0, 0));
		assertEquals(addr("CODE:07ea"), cb.getCurrentAddress());

		click(cb, 2);
		assertEquals(addr("INTMEM:55"), cb.getCurrentAddress());

		cb.goTo(new OperandFieldLocation(program, addr("CODE:03f8"), null, null, null, 1, 0));
		assertEquals(addr("CODE:03f8"), cb.getCurrentAddress());

		click(cb, 2);
		assertEquals(addr("CODE:03fe"), cb.getCurrentAddress());

		cb.goTo(new XRefFieldLocation(program, addr("INTMEM:55"), null, addr("CODE:0595"), 1, 2));
		assertEquals(addr("INTMEM:55"), cb.getCurrentAddress());

		click(cb, 2);
		assertEquals(addr("CODE:07ea"), cb.getCurrentAddress());
	}

}
